-- Fuente: https://21.edu.ar/carreras-y-programas/licenciatura-en-matematica
-- Sólo reemplaza el slide del plan; conserva portada y cierre.
UPDATE carreras
SET slides = json_set(slides, '$[1]', json('{"type":"plan_estudios","paginas":[{"izquierda":{"año":"1er Año","cuatrimestres":[{"label":"1er Cuatrimestre","materias":["Herramientas Matemáticas I - Álgebra","Geometría Analítica","Historia de la Matemática","Herramientas Matemáticas II - Análisis","Programación Lógica","Idioma Extranjero I"]},{"label":"2do Cuatrimestre","materias":["Física","Matemática Discreta","Cálculo Integral","Herramientas Matemáticas III - Estadística I","Sociología General","Idioma Extranjero II"]}]},"derecha":{"año":"2do Año","cuatrimestres":[{"label":"3er Cuatrimestre","materias":["Estática","Herramientas Matemáticas IV - Investigación Operativa","Análisis Combinatorio","Sistemas de Información","Herramientas Matemáticas V - Estadística II","Idioma Extranjero III"]},{"label":"4to Cuatrimestre","materias":["Probabilidades","Inferencia Estadística","Series y Sucesiones","Introducción a la Filosofía","Cálculo Avanzado","Idioma Extranjero IV"]}]}},{"izquierda":{"año":"3er Año","cuatrimestres":[{"label":"5to Cuatrimestre","materias":["Programación Orientada a Objetos","Grupo y Liderazgo","Métodos Estadísticos","Análisis Numérico","Ética y Deontología Profesional","Idioma Extranjero V"]},{"label":"6to Cuatrimestre","materias":["Métodos Numéricos","Tópicos de Análisis","Algoritmos y Estructura de Datos I","Variable Compleja","Idioma Extranjero VI","Seminario de Práctica de Matemática"]}]},"derecha":{"año":"4to Año","cuatrimestres":[{"label":"7mo Cuatrimestre","materias":["Algoritmo y Estructura de Datos II","Métodos Estadísticos Aplicados a la Economía","Nociones de Topología de Conjuntos","Cálculos de Varias Variables","Lógica Simbólica","Práctica Profesional de Matemática"]},{"label":"8vo Cuatrimestre","materias":["Herramientas Matemáticas VI - Modelos de Simulación","Ecuaciones Diferenciales","Nociones de Topología Algebraica","Métodos Formales","Emprendimientos Universitarios","Seminario Final de Matemática"]}]},"extras":[{"titulo":"Materias adicionales","items":["Práctica Solidaria","Materias electivas"]}]}]}'))
WHERE id = 16 AND nombre = 'Matemática' AND activa = 1
  AND json_extract(slides, '$[1].type') = 'plan_estudios';
